CREATE OR REPLACE FUNCTION public.validate_public_order() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.events WHERE id=NEW.event_id AND published AND approval_status='approved') THEN RAISE EXCEPTION 'Evento indisponível'; END IF; IF NEW.payment_method NOT IN ('multicaixa_express','referencia','unitel_money','afrimoney','paypay','transferencia') THEN RAISE EXCEPTION 'Método inválido'; END IF; IF NEW.delivery_channel NOT IN ('email','whatsapp','sms') THEN RAISE EXCEPTION 'Canal inválido'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_public_order BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.validate_public_order();
CREATE OR REPLACE FUNCTION public.get_order(p_token uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('id',o.id,'status',o.status,'total',o.total,'buyer_name',o.buyer_name,'payment_method',o.payment_method,'payment_reference',o.payment_reference,'created_at',o.created_at,'event',jsonb_build_object('name',e.name,'event_date',e.event_date,'event_time',e.event_time,'venue',e.venue,'city',e.city,'payment_info',e.payment_info),'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',g.name,'type',g.ticket_type,'quantity',i.quantity,'unit_price',i.unit_price)) FROM public.order_items i JOIN public.ticket_groups g ON g.id=i.group_id WHERE i.order_id=o.id),'[]'::jsonb),'tickets',COALESCE((SELECT jsonb_agg(jsonb_build_object('code',t.code,'status',t.status,'type',g.ticket_type,'group',g.name,'token',t.share_token) ORDER BY t.seq) FROM public.tickets t JOIN public.ticket_groups g ON g.id=t.group_id WHERE t.order_id=o.id),'[]'::jsonb)) FROM public.orders o JOIN public.events e ON e.id=o.event_id WHERE o.access_token=p_token $$;
GRANT EXECUTE ON FUNCTION public.get_order(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.group_available(_group uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT greatest(0,g.quantity - greatest(COALESCE((SELECT SUM(i.quantity) FROM public.order_items i JOIN public.orders o ON o.id=i.order_id WHERE i.group_id=g.id AND o.status IN ('pending','paid')),0)::int, (SELECT count(*)::int FROM public.tickets t WHERE t.group_id=g.id AND t.order_id IS NULL))) FROM public.ticket_groups g WHERE g.id=_group $$;